import { useCallback, useEffect, useRef, useState } from "react";
import { BOARD_SIZES, formatBoardCode, MAX_SEED, type BoardSize } from "../boardCode.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import { activateCard, advanceGame, createGame, isWon, type GameState } from "../state.ts";
import { turnAnnouncement } from "./announcement.ts";
import { formatElapsedTime, takeClockDelta } from "./clock.ts";
import { browserStorage, readBestScores, readPreferredSize, saveBestScores, savePreferredSize, type BestScores, type SessionStorage } from "./storage.ts";

export interface SessionAnnouncement {
  readonly id: number;
  readonly text: string;
}

export interface GameSession {
  readonly game: GameState;
  readonly bestMoves: number | null;
  readonly paused: boolean;
  readonly revision: number;
  readonly celebrationId: number | null;
  readonly announcement: SessionAnnouncement | null;
  readonly statusMessage: string;
  readonly activateCard: (index: number) => void;
  readonly newGame: () => void;
  readonly restart: () => void;
  readonly chooseSize: (size: BoardSize) => void;
  readonly loadBoard: (code: string) => boolean;
  readonly loadSnapshot: (text: string) => boolean;
  readonly exportSnapshot: () => string;
  readonly resume: () => void;
}

function freshGame(size: BoardSize, previousCode?: string): GameState {
  let seed = randomSeed();
  const previousSeed = previousCode?.split("-")[2];
  if (String(seed) === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
  const code = formatBoardCode(size, seed);
  if (code === null) throw new Error("Unable to create a board code.");
  const game = createGame(code);
  if (game === null) throw new Error("Unable to create a new game.");
  return game;
}

function randomSeed(): number {
  try {
    if (typeof window !== "undefined") {
      const value = window.crypto.getRandomValues(new Uint32Array(1))[0];
      if (value !== undefined) return (value % MAX_SEED) + 1;
    }
  } catch {
    // A browser without crypto can still start a playable fresh deal.
  }
  return Math.floor(Math.random() * MAX_SEED) + 1;
}

export function useGameSession(): GameSession {
  const storageRef = useRef<SessionStorage | null>(null);
  const [game, setGame] = useState<GameState>(() => {
    const storage = browserStorage();
    storageRef.current = storage;
    return freshGame(readPreferredSize(storage) ?? BOARD_SIZES[0]);
  });
  const [scores, setScores] = useState<BestScores>(() => readBestScores(storageRef.current));
  const [paused, setPaused] = useState(false);
  const [revision, setRevision] = useState(0);
  const [celebrationId, setCelebrationId] = useState<number | null>(null);
  const [announcement, setAnnouncement] = useState<SessionAnnouncement | null>(null);
  const [statusMessage, setStatusMessage] = useState("");
  const stateRef = useRef(game);
  const pausedRef = useRef(paused);
  const clockRunningRef = useRef(typeof document === "undefined" || !document.hidden);
  const lastClockRef = useRef<number | null>(null);
  const fractionRef = useRef(0);
  const announcementIdRef = useRef(0);
  const celebrationIdRef = useRef(0);
  const winEligibleRef = useRef(true);

  stateRef.current = game;
  pausedRef.current = paused;

  const announce = useCallback((text: string) => {
    announcementIdRef.current += 1;
    setAnnouncement({ id: announcementIdRef.current, text });
  }, []);

  const updateGame = useCallback((next: GameState) => {
    stateRef.current = next;
    setGame(next);
  }, []);

  const syncClock = useCallback((at: number = performance.now()): GameState => {
    if (!clockRunningRef.current || pausedRef.current) {
      lastClockRef.current = at;
      return stateRef.current;
    }
    const previous = lastClockRef.current;
    lastClockRef.current = at;
    if (previous === null) return stateRef.current;
    const delta = takeClockDelta(previous, at, fractionRef.current);
    fractionRef.current = delta.fraction;
    if (delta.milliseconds === 0) return stateRef.current;
    const current = stateRef.current;
    const next = advanceGame(current, delta.milliseconds);
    if (next !== current) updateGame(next);
    return next;
  }, [updateGame]);

  useEffect(() => {
    lastClockRef.current = performance.now();
    const timer = window.setInterval(() => syncClock(), 50);
    const onVisibility = () => {
      const now = performance.now();
      if (document.hidden) {
        syncClock(now);
        clockRunningRef.current = false;
      } else {
        lastClockRef.current = now;
        clockRunningRef.current = true;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", onVisibility);
      lastClockRef.current = null;
      clockRunningRef.current = false;
    };
  }, [syncClock]);

  const replaceGame = useCallback((next: GameState, pausedNext = false, imported = false) => {
    const now = performance.now();
    stateRef.current = next;
    pausedRef.current = pausedNext;
    lastClockRef.current = now;
    fractionRef.current = 0;
    winEligibleRef.current = !imported || !isWon(next);
    setGame(next);
    setPaused(pausedNext);
    setCelebrationId(null);
    setStatusMessage("");
    setRevision((value) => value + 1);
  }, []);

  const activate = useCallback((index: number) => {
    if (pausedRef.current) return;
    const now = performance.now();
    const previous = syncClock(now);
    const next = activateCard(previous, index);
    if (next === previous) return;
    if (!previous.started && next.started) {
      lastClockRef.current = now;
      fractionRef.current = 0;
    }
    updateGame(next);
    const result = turnAnnouncement(previous, next);
    if (result !== null) announce(result);
    if (!isWon(next) || isWon(previous)) return;
    if (winEligibleRef.current) recordBest(next, scores, storageRef.current, setScores);
    if (winEligibleRef.current) {
      celebrationIdRef.current += 1;
      setCelebrationId(celebrationIdRef.current);
    }
  }, [announce, scores, syncClock, updateGame]);

  const newGame = useCallback(() => {
    const current = stateRef.current;
    replaceGame(freshGame(current.size, current.boardCode));
  }, [replaceGame]);

  const restart = useCallback(() => {
    const next = createGame(stateRef.current.boardCode);
    if (next !== null) replaceGame(next);
  }, [replaceGame]);

  const chooseSize = useCallback((size: BoardSize) => {
    const current = stateRef.current;
    if (current.size === size) return;
    savePreferredSize(storageRef.current, size);
    replaceGame(freshGame(size, current.boardCode));
  }, [replaceGame]);

  const loadBoard = useCallback((draft: string): boolean => {
    const next = createGame(draft.trim());
    if (next === null) {
      setStatusMessage("Invalid board code.");
      announce("Invalid board code.");
      return false;
    }
    savePreferredSize(storageRef.current, next.size);
    replaceGame(next);
    setStatusMessage("Loaded board.");
    announce("Loaded board.");
    return true;
  }, [announce, replaceGame]);

  const loadSnapshot = useCallback((text: string): boolean => {
    const next = decodeSnapshot(text);
    if (next === null) {
      setStatusMessage("Invalid snapshot.");
      announce("Invalid snapshot.");
      return false;
    }
    const completed = isWon(next);
    const shouldPause = !completed;
    savePreferredSize(storageRef.current, next.size);
    replaceGame(next, shouldPause, true);
    if (completed) {
      setStatusMessage("Loaded completed snapshot.");
      announce("Loaded completed snapshot.");
    } else {
      setStatusMessage("Loaded snapshot. Select Resume to continue.");
      announce("Loaded snapshot. Select Resume to continue.");
    }
    return true;
  }, [announce, replaceGame]);

  const resume = useCallback(() => {
    if (!pausedRef.current) return;
    pausedRef.current = false;
    lastClockRef.current = performance.now();
    clockRunningRef.current = !document.hidden;
    setPaused(false);
  }, []);

  const exportSnapshot = useCallback(() => encodeSnapshot(syncClock()), [syncClock]);

  return {
    game,
    bestMoves: scores[game.size] ?? null,
    paused,
    revision,
    celebrationId,
    announcement,
    statusMessage,
    activateCard: activate,
    newGame,
    restart,
    chooseSize,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume,
  };
}

function recordBest(
  game: GameState,
  scores: BestScores,
  storage: SessionStorage | null,
  save: (scores: BestScores) => void,
): void {
  const previous = scores[game.size];
  if (previous !== undefined && previous <= game.moves) return;
  const next = { ...scores, [game.size]: game.moves };
  saveBestScores(storage, next);
  save(next);
}

