}

interface BoardProps {
  readonly game: GameState;
  readonly paused: boolean;
  readonly onActivate: (index: number) => void;
}

export const Board = forwardRef<BoardHandle, BoardProps>(function Board({ game, paused, onActivate }, ref) {
