    const cardBox = card.getBoundingClientRect();
    const areaBox = area.getBoundingClientRect();
    let left = area.scrollLeft;
    let top = area.scrollTop;
    if (cardBox.left < areaBox.left + 11) left -= areaBox.left + 11 - cardBox.left;
    else if (cardBox.right > areaBox.right - 11) left += cardBox.right - areaBox.right + 11;
    if (cardBox.top < areaBox.top + 11) top -= areaBox.top + 11 - cardBox.top;
    else if (cardBox.bottom > areaBox.bottom - 11) top += cardBox.bottom - areaBox.bottom + 11;
    if (left !== area.scrollLeft || top !== area.scrollTop) area.scrollTo({ left, top, behavior: "auto" });
  }

  function handleKey(index: number, event: ReactKeyboardEvent<HTMLButtonElement>): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    let next = index;
    if (event.key === "ArrowLeft" && index % game.size > 0) next -= 1;
    else if (event.key === "ArrowRight" && index % game.size < game.size - 1) next += 1;
    else if (event.key === "ArrowUp" && index >= game.size) next -= game.size;
    else if (event.key === "ArrowDown" && index + game.size < game.deck.length) next += game.size;
    else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onActivate(index);
      return;
    } else return;
    event.preventDefault();
    focusCard(next);
  }

  const matched = new Set(game.matched);
  const selected = game.selection.kind === "one"
    ? [game.selection.index]
    : game.selection.kind === "mismatch" ? [game.selection.first, game.selection.second] : [];
  return (
    <div className="board-scroll" ref={scrollArea} aria-label="Card board">
      <div className="board-grid" style={{ "--board-size": game.size } as React.CSSProperties}>
        {game.deck.map((faceId, index) => (
          <Card
            key={index}
            index={index}
            columns={game.size}
            faceId={faceId}
            revealed={selected.includes(index)}
            matched={matched.has(index)}
            tabIndex={tabStop === index ? 0 : -1}
            cardRef={(element) => { buttons.current[index] = element; }}
            onActivate={() => onActivate(index)}
            onFocus={() => { remembered.current = index; setTabStop(index); scrollFocusedCard(index); }}
            onKeyDown={(event) => handleKey(index, event)}
          />
        ))}
      </div>
      {paused ? <p className="board-pause-note">Paused. Use Resume to continue.</p> : null}
    </div>
  );
});
import type { KeyboardEvent as ReactKeyboardEvent, RefCallback } from "react";
import { describeFace } from "./faceData.ts";
import { CardBack, FaceArtwork } from "./FaceArtwork.tsx";

interface CardProps {
  readonly index: number;
  readonly columns: number;
  readonly faceId: number;
  readonly revealed: boolean;
  readonly matched: boolean;
  readonly tabIndex: 0 | -1;
  readonly cardRef: RefCallback<HTMLButtonElement>;
  readonly onActivate: () => void;
  readonly onFocus: () => void;
  readonly onKeyDown: (event: ReactKeyboardEvent<HTMLButtonElement>) => void;
}

export function Card({ index, columns, faceId, revealed, matched, tabIndex, cardRef, onActivate, onFocus, onKeyDown }: CardProps) {
  const showFace = revealed || matched;
  const position = `Row ${Math.floor(index / columns) + 1}, column ${index % columns + 1}`;
  const face = showFace ? describeFace(faceId) : null;
  const state = matched ? "matched" : showFace ? "revealed" : "closed";
  const label = face === null ? `${position}, ${state}` : `${position}, ${face.name}, ${state}`;
  return (
    <button
      ref={cardRef}
      type="button"
      className={`memory-card${showFace ? " is-face" : ""}${matched ? " is-matched" : ""}`}
      aria-label={label}
      aria-disabled={matched || undefined}
      aria-pressed={showFace}
      tabIndex={tabIndex}
      onClick={(event) => { if (event.button === 0) onActivate(); }}
      onFocus={onFocus}
      onKeyDown={onKeyDown}
    >
      {showFace ? <FaceArtwork faceId={faceId} /> : <CardBack />}
      {matched ? <span className="match-check" aria-hidden="true">✓</span> : null}
    </button>
  );
}
