  await expect(banner).toHaveCSS("animation-iteration-count", "1");
  await expect(banner).toHaveAttribute("data-pulse-starts", "1");
  await page.clock.runFor(601);
  await expect(banner).toHaveAttribute("data-pulse-ends", "1");
